{
  "segment_function": "argument",
  "claims": [
    {
      "claim": "Fabrication consists in reification, which inherently involves an element of violation and violence against nature as materials are killed, interrupted, or torn from their natural locations.",
      "claim_type": "author_position",
      "supporting_excerpt": "Fabrication, the work of homo faber , consists in reification. Solidity, inherent in all, even the most fragile, things, comes from the material worked upon, but this material itself is not simply given and there... Material is already a product of human hands which have removed it from its natural location, either killing a life process... or interrupting one of nature’s slower processes... This element of violation and violence is present in all fabrication, and homo faber , the creator of the human artifice, has always been a destroyer of nature.",
      "support_kind": "direct",
      "confidence": 1
    },
    {
      "claim": "The experience of violence in fabrication constitutes the elemental experience of human strength, providing self-assurance and satisfaction distinct from the pleasure or exhaustion of sheer labor.",
      "claim_type": "author_position",
      "supporting_excerpt": "The experience of this violence is the most elemental experience of human strength and, therefore, the very opposite of the painful, exhausting effort experienced in sheer labor. It can provide self-assurance and satisfaction, and can even become a source of self-confidence throughout life",
      "support_kind": "direct",
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "Fabrication",
      "definition": "The work of homo faber that consists in reification, involving the destruction or violation of nature to build the human artifice."
    }
  ],
  "distinctions": [
    {
      "item_a": "animal laborans",
      "item_b": "homo faber",
      "distinction": "The animal laborans remains the servant of nature and the earth, whereas homo faber conducts himself as lord and master of the whole earth through destruction and fabrication."
    }
  ],
